# Define a class to represent a more complex system for managing tasks
class TaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        # Add a new task to the list
        self.tasks.append(task)

    def remove_task(self, task):
        # Remove a task from the list if it exists
        if task in self.tasks:
            self.tasks.remove(task)

    def get_all_tasks(self):
        # Return a list of all current tasks
        return self.tasks

    def complete_task(self, task):
        # Mark a task as completed (if it exists)
        if task in self.tasks:
            self.tasks.remove(task)
            print(f"Task '{task}' marked as completed.")
        else:
            print(f"Task '{task}' not found.")

# Example usage of the TaskManager class
if __name__ == "__main__":
    manager = TaskManager()
    manager.add_task("Buy groceries")
    manager.add_task("Clean the house")
    print("All Tasks:", manager.get_all_tasks())
    manager.complete_task("Buy groceries")
    print("Remaining Tasks:", manager.get_all_tasks())
```

